      "module_name": "Mathlib.LinearAlgebra.Matrix.Determinant.Basic",
      "kind": "theorem",
      "type": "∀ {m : Type u_1} [inst : DecidableEq m] [inst_1 : Fintype m] {R : Type v} [inst_2 : CommRing R] [IsDomain R]\n  {A : Matrix m m R}, A.det ≠ 0 → LinearIndependent R fun i => A i"
