    },
    {
      "name": "Matrix.det_eq_zero_of_not_linearIndependent_rows",
      "module_name": "Mathlib.LinearAlgebra.Matrix.Determinant.Basic",
      "kind": "theorem",
      "type": "∀ {m : Type u_1} [inst : DecidableEq m] [inst_1 : Fintype m] {R : Type v} [inst_2 : CommRing R] [IsDomain R]\n  {A : Matrix m m R}, (¬LinearIndependent R fun i => A i) → A.det = 0"
